// Generated by cpp-anything bridge for a C unit: the original, called as it is.
// Symbols are renamed at compile time (-D), so the port can keep the real names.
#include <sys/wait.h>
#include <unistd.h>

#include <cerrno>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include "cppan/json.hpp"


  int cppan_original_word_count(const char * text);
  int cppan_original_digits_only(const char * text);
  double cppan_original_average_word_length(const char * text);
  int cppan_original_sum_ascii(const char * text);
  std::string cppan_original_trim_copy(const std::string& text);
  std::string cppan_original_repeat_join(const std::string& text, int times);
  void cppan_original_print_words(const char * text);



namespace {

using cppan::Json;

Json error_json(const char* type, const std::string& message) {
  Json::Object fields;
  fields.emplace_back("type", Json::string(type));
  fields.emplace_back("msg", Json::string(message));
  Json::Object out;
  out.emplace_back("err", Json::object(std::move(fields)));
  return Json::object(std::move(out));
}

Json ok_json(Json value) {
  Json::Object out;
  out.emplace_back("ok", std::move(value));
  return Json::object(std::move(out));
}

std::string read_all(const char* path) {
  std::FILE* file = std::fopen(path, "rb");
  if (file == nullptr) return {};
  std::string out;
  char buffer[8192];
  std::size_t got = 0;
  while ((got = std::fread(buffer, 1, sizeof buffer, file)) > 0) out.append(buffer, got);
  std::fclose(file);
  return out;
}

Json call_function(const std::string& name, const std::vector<Json>& args);

}  // namespace

int main(int argc, char** argv) {
  const char* in_path = nullptr;
  const char* out_path = nullptr;
  long bench = 0;
  for (int index = 1; index < argc; ++index) {
    if (std::strcmp(argv[index], "--cases") == 0 && index + 1 < argc) {
      in_path = argv[++index];
    } else if (std::strcmp(argv[index], "--out") == 0 && index + 1 < argc) {
      out_path = argv[++index];
    } else if (std::strcmp(argv[index], "--bench") == 0 && index + 1 < argc) {
      bench = std::atol(argv[++index]);
    }
  }
  if (in_path == nullptr) {
    std::fprintf(stderr, "cppan_harness: --cases FILE is required\n");
    return 2;
  }
  std::FILE* out = out_path != nullptr ? std::fopen(out_path, "wb") : stdout;
  if (out == nullptr) {
    std::perror(out_path);
    return 2;
  }
  const std::string text = read_all(in_path);
  std::vector<std::string> lines;
  std::string current;
  for (const char ch : text) {
    if (ch == '\n') {
      if (!current.empty()) lines.push_back(current);
      current.clear();
    } else {
      current.push_back(ch);
    }
  }
  if (!current.empty()) lines.push_back(current);

  std::size_t sink = 0;
  const auto start = std::chrono::steady_clock::now();
  const long repeats = bench > 0 ? bench : 1;
  for (long repeat = 0; repeat < repeats; ++repeat) {
    for (const auto& line : lines) {
      Json call;
      try {
        call = cppan::parse(line);
      } catch (const std::exception& error) {
        std::fprintf(stderr, "cppan_harness: %s\n", error.what());
        return 2;
      }
      const Json* id = call.find("id");
      const Json* fn = call.find("fn");
      if (id == nullptr || fn == nullptr) continue;
      std::string name = fn->as_string();
      std::vector<Json> args;
      if (const Json* list = call.find("args"); list != nullptr) args = list->as_array();
      if (bench > 0) {
        sink += cppan::dump(call_function(name, args)).size();
        continue;
      }
      // Fork per case: a segfault is a case, and undefined behaviour cannot take
      // the whole recording down.
      int pipefd[2];
      if (::pipe(pipefd) != 0) {
        std::perror("pipe");
        return 2;
      }
      const pid_t child = ::fork();
      if (child == 0) {
        ::close(pipefd[0]);
        const std::string payload = cppan::dump(call_function(name, args));
        ::write(pipefd[1], payload.data(), payload.size());
        ::close(pipefd[1]);
        ::_exit(0);
      }
      ::close(pipefd[1]);
      std::string payload;
      char buffer[8192];
      ssize_t got = 0;
      while ((got = ::read(pipefd[0], buffer, sizeof buffer)) > 0) {
        payload.append(buffer, static_cast<std::size_t>(got));
      }
      ::close(pipefd[0]);
      int status = 0;
      ::waitpid(child, &status, 0);
      Json::Object entry;
      entry.emplace_back("id", Json::string(id->as_string()));
      if (WIFSIGNALED(status)) {
        char signal_text[32];
        std::snprintf(signal_text, sizeof signal_text, "SIG%d", WTERMSIG(status));
        entry.emplace_back("result", error_json("Crash", signal_text));
      } else if (payload.empty()) {
        entry.emplace_back("result", error_json("CppError", "no result"));
      } else {
        try {
          entry.emplace_back("result", cppan::parse(payload));
        } catch (const std::exception& error) {
          entry.emplace_back("result", error_json("CppError", error.what()));
        }
      }
      const std::string line_out = cppan::dump(Json::object(std::move(entry)));
      std::fwrite(line_out.data(), 1, line_out.size(), out);
      std::fputc('\n', out);
    }
  }
  if (bench > 0) {
    const auto stop = std::chrono::steady_clock::now();
    const double nanos = std::chrono::duration<double, std::nano>(stop - start).count();
    const double calls = static_cast<double>(repeats) * static_cast<double>(lines.size());
    // The original may itself print (printf in the unit): the bench number goes to
    // stderr so it is the only thing a caller has to parse.
    std::fprintf(stderr, "{\"calls\":%lld,\"ns_per_call\":%f,\"sink\":%zu}\n",
                 static_cast<long long>(calls), nanos / calls, sink);
  }
  if (out != stdout) std::fclose(out);
  return 0;
}

namespace {

Json call_function(const std::string& name, const std::vector<Json>& args) {
  try {
    if (name == "word_count") {
      const std::string arg0_text = args.at(0).as_string();
      const char* arg0 = arg0_text.c_str();
      return ok_json(Json::integer(static_cast<std::int64_t>(cppan_original_word_count(arg0))));
    }
    if (name == "digits_only") {
      const std::string arg0_text = args.at(0).as_string();
      const char* arg0 = arg0_text.c_str();
      return ok_json(Json::integer(static_cast<std::int64_t>(cppan_original_digits_only(arg0))));
    }
    if (name == "average_word_length") {
      const std::string arg0_text = args.at(0).as_string();
      const char* arg0 = arg0_text.c_str();
      return ok_json(Json::real(static_cast<double>(cppan_original_average_word_length(arg0))));
    }
    if (name == "sum_ascii") {
      const std::string arg0_text = args.at(0).as_string();
      const char* arg0 = arg0_text.c_str();
      return ok_json(Json::integer(static_cast<std::int64_t>(cppan_original_sum_ascii(arg0))));
    }
    if (name == "trim_copy") {
      const std::string arg0_text = args.at(0).as_string();
      const std::string& arg0 = arg0_text;
      const std::string result = cppan_original_trim_copy(arg0);
      return ok_json(Json::string(result));
    }
    if (name == "repeat_join") {
      const std::string arg0_text = args.at(0).as_string();
      const std::string& arg0 = arg0_text;
      const auto arg1 = static_cast<long long>(args.at(1).as_int());
      const std::string result = cppan_original_repeat_join(arg0, arg1);
      return ok_json(Json::string(result));
    }
    if (name == "print_words") {
      const std::string arg0_text = args.at(0).as_string();
      const char* arg0 = arg0_text.c_str();
      cppan_original_print_words(arg0);
      return ok_json(Json::null());
    }

    return error_json("UnknownFunction", name);
  } catch (const std::exception& error) {
    return error_json("CppError", error.what());
  }
}

}  // namespace
